alter table public.datasets add column if not exists preview_rows jsonb;
alter table public.datasets add column if not exists locked_preview jsonb;

update public.datasets
set preview_rows = $prev${"columns": ["Deal ID", "Enquiry Date", "Booking Date", "Sales Person", "Emp Code", "Branch", "Branch Code", "Month", "Model", "Variant", "Variant Tier", "Fuel", "Transmission", "Colour", "Model Year", "Seating Capacity", "Safety Rating", "Ex-Showroom Price", "Floor Price", "Quoted Price", "Discount Given", "Scheme Applied", "Final Sale Price", "Accessories Interest", "Accessories Value", "Post Delivery Accessory Value", "Payment Mode", "Down Payment", "Finance Amount", "Finance Bank", "Loan Tenure", "Interest Rate", "Customer Name", "Contact", "Family Size", "Customer Type", "Status", "Scheduled Delivery Date", "Actual Delivery Date", "Customer Feedback", "Remarks"], "rows": [["SM501320", "17-05-25", "27 May 2025", " Devendra Chopra", "EMP1017", "Pitampura", "SM-PTP", "", "Tata Nexon EV", "Creative Plus 30", "Base", "ELECTRIC", "Automatic", "Ocean Blue", "MY2025", "5", "5 Star", "  1249000  ", "Rs 11,04,951", "  1311067  ", "  46447  ", "Corporate Discount", "Rs 11,81,582", "1", "Rs 49,546", "", "Finance", "Rs 4,41,189", "  740392  ", "HDFC Bank", "72", "8.57 %", "Devendra Arora", "9443178223", "4", "First Time Buyer", "Booked", "12-06-25", "16-06-25", "Charging range", ""], ["SM510750", "13/12/2025", "24/12/2025", "RITU AGARWAL", "EMP1050", "Okhla", "SM-OKH", "", "Tata Tigor", "XM", "Base", "Petrol", "M/T", "Supernova Copper", "MY2025", "5", "4 Star", "Rs 5,70,000", "Rs 4,96,890", "Rs 6,20,713", "Rs 57,151", "Exchange Bonus", "", "N", "", "", "Cash", "", "", "", "", "", "Arun Ahuja", "", "3", "First Time Buyer", "Follow up", "", "", "5-star safety rating", "customer will think and confirm"], ["SM501512", "14-04-25", "22-05-25", "SURESH RAO", "EMP1029", "Janakpuri", "SM-JKP", "May-25", "Tata Tiago", "Pure Plus A", "Mid", "P", "Manual", "Daytona Grey", "MY2025", "5", "4 Star", "Rs 6,90,000", "689611.00", "715794.00", "17131.00", "Scrappage Benefit", "695075.00", "N", "", "", "Finance", "157342.00", "Rs 5,37,734", "Axis Bank", "36 months", "10.06 %", "Suresh Ahuja", "", "2", "Repeat Customer", "CLOSED", "06-06-25", "17-06-25", "Ride comfort", "full payment received"], ["SM513702", "17/02/2026", "27 Mar 2026", "KIRTI YADAV", "EMP01022", "Karol Bagh", "SM-KRB", "", "Tata Nexon", "Smart", "Base", "P", "Manual", "Pure Grey", "MY2026", "5", "5 Star", "740000.00", "696918.00", "  763007  ", "24162.00", "Exchange Bonus", "", "Y", "", "", "Finance", "", "", "", "", "", "Sarita Khanna", "9898935876", "3", "First Time Buyer", "Follow-up", "", "", "ADAS features", "wants more discount"], ["SM500402", "20/02/2025", "05 Apr 2025", "Sanjay Bedi ", "EMP1021", "Pitampura", "SM-PTP", "Apr-25", "Tata Tigor EV", "XE", "Base", "ELECTRIC", "Auto", "Daytona Grey", "MY2025", "5", "4 Star", "1249000.00", "1102283.00", "12.90 L", "30365.00", "Exchange Bonus", "", "Y", "", "", "Finance", "", "", "", "", "", "Vishal Dubey", "9019983371", "3 members", "First Time Buyer", "Follow up", "", "", "Price and value for money", "comparing with competitor"]], "total_rows": 14735}$prev$::jsonb,
    locked_preview = $lock${"summary": "A full four phase analyst project built on 14,735 rows across 41 columns of hand typed dealership ERP data. You clean it, you query it, you build a two page dashboard on it, then you write the recommendation that settles the bonus argument.", "phases": [{"title": "Phase 1, Python: Clean the Data", "blurb": "Turn the raw ERP export into a trustworthy table. Nothing later works until this does.", "count": 7, "sample": ["Load the raw CSV/XLSX and profile it: row count, column count, null counts per column, and a written note on the five things that look most wrong before you touch anything.", "Remove duplicate deal entries (~190 of them). State your de-duplication rule and how many genuine deals remain."]}, {"title": "Phase 2, SQL: Answer the Business Questions", "blurb": "Settle the arguments management cannot settle themselves, with evidence.", "count": 12, "sample": ["Rank the 56 salespeople by number of Closed deals. Return name, branch, deals closed and their rank.", "For each salesperson, compute conversion rate: Closed / (Closed+Open+Lost). Return anyone above 75% conversion, ordered by conversion descending."]}, {"title": "Phase 3a, Dashboard Page 1: Deal Lookup", "blurb": "Type a Deal ID, get everything about that person, that car, that price, that timeline.", "count": 5, "sample": ["Build a search box that takes a Deal ID and returns everything about that one deal on a single screen: salesperson + branch, car (model/variant/tier/fuel/colour/model year), the full price chain (ex-showroom → floor → quoted → discount → final), payment/finance detail, and the delivery timeline (enquiry → booking → scheduled → actual, with the gap called out).", "On the same lookup screen, show customer context: family size, customer type, accessories taken, the face-to-face feedback reason, and any remarks."]}, {"title": "Phase 3b, Dashboard Page 2: Analytics", "blurb": "The analytics page management actually lives in.", "count": 10, "sample": ["Build a salesperson leaderboard panel showing volume, total margin and average margin per deal side by side, so 'best' is never reduced to one number the viewer can't question.", "Add an average sale price panel, sliceable by Model, Branch and Variant Tier."]}, {"title": "Phase 4, Documentation", "blurb": "Write the recommendation you would actually hand a director.", "count": 1, "sample": ["Write a short project write-up (any format, Word, PDF, Notion, a README, doesn't matter) with three sections: (1) **Process Flow**, how you actually went from the raw export to your cleaned data to your SQL answers to your dashboard, including the decisions you made (especially how you resolved salesperson identity); (2) **Key Discoveries**, your top 3–5 findings, stated as a decision-maker would want to hear them, not as code output; (3) **Future Growth Recommendations**, at least 3 concrete, data-backed recommendations for what Sanchay Motors should actually do next. This document is the deliverable a hiring manager or client would actually read, treat it that way."]}, {"title": "Stretch ideas (optional)", "blurb": "Optional extras, a personal pick of 3 for every buyer.", "count": 6, "sample": ["Build a single composite salesperson scorecard combining volume, margin, conversion and below-floor discipline into one number. Defend your weights.", "Model the enquiry-to-booking gap: do faster-closing deals earn better or worse margins?"]}], "premium_count": 5, "total_tasks": 41}$lock$::jsonb
where slug = 'tata-delhi-sales-fy2526';

-- Replace em dashes in seeded catalogue copy
update public.datasets
set title = replace(replace(title, ' — ', ': '), '—', ','),
    short_description = replace(replace(short_description, ' — ', ', '), '—', ','),
    long_description = replace(replace(long_description, ' — ', ', '), '—', ',');

update public.folders
set description = replace(replace(description, ' — ', ', '), '—', ',');

-- Replace em dashes inside the 100 personalised task packs, claims preserved
update public.dataset_licenses
set task_pack = replace(replace(task_pack::text, ' — ', ', '), '—', ',')::jsonb;

